[CmdletBinding()]param([Parameter(Mandatory)][string]$Affected,[Parameter(Mandatory)][string]$Repository,[Parameter(Mandatory)][string]$Ref,[Parameter(Mandatory)][string]$SourceSha,[Parameter(Mandatory)][string]$DiscoveryRunId,[Parameter(Mandatory)][string]$Workflow,[ValidateSet('true','false')][string]$PublishContainers='false')
$manifest=Get-Content -LiteralPath $Affected -Raw|ConvertFrom-Json;if(-not $manifest.affectedApplications.Count){Write-Host 'No affected applications; build-and-test workflow was not dispatched.';return};if(-not $env:GITHUB_TOKEN){throw 'GITHUB_TOKEN is required'};$api=if($env:GITHUB_API_URL){$env:GITHUB_API_URL}else{'https://api.github.com'};$uri="$api/repos/$Repository/actions/workflows/$([uri]::EscapeDataString($Workflow))/dispatches";$body=@{ref=$Ref;inputs=@{source_sha=$SourceSha;discovery_run_id=$DiscoveryRunId;publish_containers=$PublishContainers}}|ConvertTo-Json -Depth 10 -Compress;$headers=@{Accept='application/vnd.github+json';Authorization="Bearer $env:GITHUB_TOKEN";'X-GitHub-Api-Version'='2022-11-28'};Invoke-RestMethod -Method Post -Uri $uri -Headers $headers -ContentType 'application/json' -Body $body;Write-Host "Dispatched build-and-test workflow for $($manifest.affectedApplications.Count) application(s)."
